	  	SELECT count(*)
		  FROM
			(SELECT A.*
				  , rownum AS rn
			   FROM (SELECT q.*
			   		   FROM product_tbl p
			   		      , qna_tbl q
			   		      , user_tbl u
					  WHERE p.pd_id = q.pd_id
					  	AND u.u_member_id = q.u_member_id

				  		AND q.q_category = #{q_category}



			  			AND q.q_regDate >= #{from}




    					AND q.q_regDate <= #{to}



    					AND q.q_answer = #{q_answer}


    					AND q.u_member_id = #{sessionId}

    				) A
			)

  	SELECT *
	  FROM
		(SELECT A.*, rownum AS rn
		   FROM (SELECT q.*,
		   				u.u_id
		   		   FROM product_tbl p
		   		      , qna_tbl q
		   		      , user_tbl u
				  WHERE p.pd_id = q.pd_id
				  	AND u.u_member_id = q.u_member_id

				  		AND q.q_category = #{q_category}



			  			AND q.q_regDate >= #{from}




    					AND q.q_regDate <= #{to}



    					AND q.q_answer = #{q_answer}


    					AND q.u_member_id = #{sessionId}

			   ORDER BY q.q_regdate DESC) A 
		)
	WHERE rn BETWEEN #{start} AND #{end}
	ORDER BY rn ASC

	SELECT COUNT(*)
    FROM user_tbl
    WHERE u_id = #{u_id}
      AND u_password = #{u_password, jdbcType=VARCHAR}
      AND u_show = 'Y'

